import sys; sys.path.insert(0,'/workspace/stitch')
import stitch, json, time, os, curlcall
P=open('project_id.txt').read().strip()
mode=sys.argv[1]
ds=json.load(open('design_systems.json'))[mode]['name']
pal={'LIGHT':"LIGHT mode: warm cream background #FBF4EC, white cards #FFFFFF with soft warm shadows and 1px #F0E3D6 borders. Ink espresso #2B1D14, secondary #8C7B6E. ONE accent gradient orange #E8622C to terracotta #C9502A for the primary CTA, active chip/category and active bottom-nav item; peach #FDE3D2 for icon circles. Gold #F2A93B rating star, green #4E9A5B only for the words 'Free delivery'.",
'DARK':"DARK mode in warm espresso brown (NOT pure black, NOT blue/navy, NOT purple): background #1B1411, cards/surfaces #2A201B with 1px rgba(255,236,220,0.08) borders, ink #F8EDE3, secondary #A8968A. Same orange gradient #F0703A to #D4572B for the CTA, active category and active nav. Icon circles #3A2A22. Gold #F2A93B star, green #6FBF7C only for 'Free delivery'. No neon glow."}[mode]
base=f"""Mobile food delivery app (customer ordering) called "Ember". Warm editorial minimal style. {pal} Display headings in an elegant SERIF (Newsreader) with ONE italic orange accent phrase; all UI text in DM Sans (clean geometric sans). Real overhead food photography with soft shadows, 20px radius cards, full-round pill chips and a pill search bar, thin rounded line icons. NO emoji, NO illustrations. Content must fit a 390x844 viewport, airy spacing. Prices in US dollars."""
nav=" Bottom tab bar (white/surface, rounded top, soft shadow) with 5 icons + small labels: Home, Search, Orders, Saved, Profile."
screens={
'home':base+""" Screen: HOME. Top row: small round avatar left with muted "Deliver to" and bold "24 Park Lane" with a chevron, right a round bell icon button. Big serif headline in 2 lines: "Fresh & warm," then italic orange "at your door". To the right of / under the headline a big overhead photo of a colourful food bowl (poke/buddha bowl) on a round plate with soft drop shadow, partly overlapping. Pill search bar "Search dishes or restaurants" with an orange round filter button. Category row of 5 round icon chips with labels below: Burgers, Pizza, Asian, Healthy, More (Burgers active: orange filled circle with white icon; others peach circles). A rounded promo card with orange-to-peach gradient (#E8622C to #F6A77A): small label "Weekend deal", serif "30% off your first order", a white pill code chip "EMBER30" and a small food photo on the right. Section "Popular near you" with "See all" orange link, then a 2-column grid of restaurant cards (photo top 16px radius, name, star 4.8, muted "20-25 min · Free delivery"): "Harvest Bowl Co." and "Napoli Wood Fire"."""+nav+" Home active in orange.",
'detail':base+""" Screen: DISH DETAIL with add to cart. Top 40 percent: a large round overhead photo of a colourful tofu grain bowl centered on a soft peach-cream backdrop with a soft drop shadow; a round back button at top left and a round heart button at top right. Below it a rounded content sheet: small muted restaurant name "Harvest Bowl Co.", serif dish title "Sesame Tofu Bowl" with the price "$14.50" in orange on the right. A row of three small pills: rating 4.8, 15-20 min, 540 kcal. Two lines of muted description: "Crispy sesame tofu, edamame, soft egg, sweet corn, cucumber and red cabbage with miso-ginger dressing." Section heading "Add extras" and three option rows, each with a small round photo, a name, a price and a round checkbox on the right: "Extra avocado" +$1.50 (checked, orange), "Edamame" +$1.00, "Add salmon" +$3.00. Fixed bottom bar: a quantity stepper pill showing minus, 1, plus on the left and a wide orange gradient pill button "Add to cart  $16.00" on the right. This screen has no tab bar.""",
'cart':base+""" Screen: CART AND CHECKOUT. Header with a round back button on the left, centered serif title "My Cart" and a muted "Clear" text button on the right. A white delivery card: map pin icon in a peach circle, small muted "Deliver to", bold "Home, 24 Park Lane, Apt 5", orange "Change" link on the right, and below it a small peach pill "Arrives in 25-30 min". Label "3 items". Three cart item cards, each with a square rounded food photo on the left, the dish name, a muted note, the price in bold and a small quantity stepper showing minus, 1, plus: "Sesame Tofu Bowl" with note "Extra avocado" for $16.00, "Margherita Pizza" with note "Napoli Wood Fire" for $12.00, "Iced Matcha Latte" with note "Oat milk" for $4.50. A promo row with a dashed orange border, tag icon, text "EMBER30 applied" and orange "-$9.75". A bill summary card with rows Subtotal $32.50, Delivery fee Free (green), Promo EMBER30 -$9.75, a thin divider and a bold serif Total $22.75. A payment row with a card icon and "Visa ending 4242" and a chevron. Fixed bottom: a full-width orange gradient pill button "Place order  $22.75". This screen has no tab bar.""",
}
which=sys.argv[2:] or list(screens)
LOGF=f'gen_log_{mode.lower()}.json'
log=json.load(open(LOGF)) if os.path.exists(LOGF) else {}
for k in which:
    for attempt in range(8):
        t=time.time(); print('START',mode,k,attempt,flush=True)
        try:
            r=curlcall.call('generate_screen_from_text',{'projectId':P,'prompt':screens[k],'deviceType':'MOBILE','designSystem':ds},timeout=900)
        except Exception as e:
            print("EXC",round(time.time()-t),"s",e,flush=True); time.sleep(30); continue
        log[f'{mode}-{k}']=r; json.dump(log,open(LOGF,'w'),indent=1)
        print(mode,k,round(time.time()-t),'s',json.dumps(r)[:300],flush=True)
        if 'screens' in json.dumps(r): break
